    fields = [('name','What’s your name?','<input id="name" name="name" autocomplete="name" maxlength="100" required>','Use the name you’d like us to use.'),('email','Where can we reply?','<input id="email" name="email" type="email" autocomplete="email" maxlength="254" required>','Your email is used to respond to this request.'),('area','Where are you based?','<input id="area" name="area" autocomplete="address-level2" maxlength="120" required>','Town or neighborhood only. No street address needed.'),('who','Who would you like help for?','<select id="who" name="who_for" required><option value="">Choose one</option><option>My child or children</option><option>Myself</option><option>An older adult</option><option>Our whole household</option></select>','For an independent adult, changes need their permission.'),('concern','What’s on your mind?','<textarea id="concern" name="main_concern" rows="3" maxlength="800" required></textarea>','A general concern is enough. No passwords, codes, children’s names or financial details.'),('phone','Would you like to add a phone number?','<input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="40">','Optional. Leave blank to skip.')]
